package com.modelrag.knowledge.controller;
import com.modelrag.common.cache.QaAnswerCache; import com.modelrag.common.dto.ApiResponse; import com.modelrag.common.outbox.IndexOutbox; import com.modelrag.common.security.AccessControlService; import com.modelrag.common.sse.SseEmitterService; import com.modelrag.common.vector.VectorStore; import com.modelrag.knowledge.model.*; import com.modelrag.knowledge.service.*; import java.util.*; import org.springframework.http.MediaType; import org.springframework.web.bind.annotation.*; import org.springframework.web.multipart.MultipartFile; import org.springframework.web.servlet.mvc.method.annotation.SseEmitter;
@RestController @RequestMapping("/api/v1/knowledge-bases/{datasetId}/documents") public class DocumentController {private final DocumentService docs;private final KnowledgeStore store;private final SseEmitterService sse;private final QaAnswerCache answers;private final IndexOutbox outbox;private final VectorStore vectors;private final AccessControlService access;public DocumentController(DocumentService d,KnowledgeStore s,SseEmitterService se,QaAnswerCache a,IndexOutbox o,VectorStore v,AccessControlService access){docs=d;store=s;sse=se;answers=a;outbox=o;vectors=v;this.access=access;}@PostMapping public ApiResponse<Document> upload(@PathVariable long datasetId,@RequestParam MultipartFile file)throws Exception{access.requireRole("ADMIN");Document document=docs.upload(datasetId,file);answers.invalidateDataset(datasetId);return ApiResponse.success(document);}@GetMapping public ApiResponse<List<Document>> list(@PathVariable long datasetId){access.requireDatasetAccess(datasetId);return ApiResponse.success(store.documents(datasetId));}@DeleteMapping("/{documentId}")public ApiResponse<Void> delete(@PathVariable long datasetId,@PathVariable long documentId){access.requireRole("ADMIN");store.chunks(datasetId).stream().filter(c->c.documentId()==documentId).forEach(c->outbox.append("DELETE_CHUNK",datasetId,documentId,c.id(),"{}"));vectors.deleteDocument(documentId);store.deleteDocument(datasetId,documentId);answers.invalidateDataset(datasetId);return ApiResponse.success(null);}@GetMapping("/{documentId}/chunks") public ApiResponse<List<Chunk>> chunks(@PathVariable long datasetId,@PathVariable long documentId){access.requireDatasetAccess(datasetId);return ApiResponse.success(store.chunks(datasetId).stream().filter(c->c.documentId()==documentId).toList());}@GetMapping(value="/{documentId}/stream",produces=MediaType.TEXT_EVENT_STREAM_VALUE)public SseEmitter stream(@PathVariable long datasetId,@PathVariable long documentId){access.requireDatasetAccess(datasetId);store.document(documentId);return sse.subscribe("document:"+documentId);}}
